import React, { useState, useContext } from "react";
import Layout, { SectionContext } from "./components/Layout";
import Dashboard from "./components/Dashboard";
import GoalForm from "./components/GoalForm";
import Overview from "./components/Overview";

const API_URL = "http://localhost:3001/api/plans/calculate";

const AppContent = () => {
  const { activeSection } = useContext(SectionContext);
  const [goals, setGoals] = useState([]);
  const [income, setIncome] = useState(0);
  const [showGoalForm, setShowGoalForm] = useState(false);
  const [editGoal, setEditGoal] = useState(null);
  const [plan, setPlan] = useState({ goals: [], totalMonthlyNeeded: 0, disposableIncome: 0 });

  React.useEffect(() => {
    if (goals.length === 0 || !income) {
      setPlan({ goals, totalMonthlyNeeded: 0, disposableIncome: income });
      return;
    }
    fetch(API_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ goals, disposableIncome: income }),
    })
      .then((res) => res.json())
      .then((data) => setPlan(data))
      .catch(() => setPlan({ goals, totalMonthlyNeeded: 0, disposableIncome: income }));
  }, [goals, income]);

  const addGoal = (goal) => {
    setGoals((prev) => [...prev, goal]);
  };

  const removeGoal = (id) => {
    setGoals((prev) => prev.filter((g) => g.id !== id));
  };

  const updateIncome = (value) => {
    setIncome(value);
  };

  const handleEditGoal = (goal) => {
    setEditGoal(goal);
    setShowGoalForm(true);
  };

  const handleSaveGoal = (goal) => {
    if (editGoal) {
      setGoals((prev) => prev.map((g) => (g.id === goal.id ? goal : g)));
      setEditGoal(null);
    } else {
      addGoal(goal);
    }
    setShowGoalForm(false);
  };

  let content;
  if (activeSection === "home") {
    content = (
      <Dashboard
        goals={plan.goals.length ? plan.goals : goals}
        income={income}
        onRemoveGoal={removeGoal}
        onShowGoalForm={() => setShowGoalForm(true)}
        onEditGoal={handleEditGoal}
        totalMonthlyNeeded={plan.totalMonthlyNeeded}
      />
    );
  } else if (activeSection === "goals") {
    content = (
      <Dashboard
        goals={plan.goals.length ? plan.goals : goals}
        income={income}
        onRemoveGoal={removeGoal}
        onShowGoalForm={() => setShowGoalForm(true)}
        onEditGoal={handleEditGoal}
        totalMonthlyNeeded={plan.totalMonthlyNeeded}
      />
    );
  } else if (activeSection === "overview") {
    content = <Overview goals={plan.goals.length ? plan.goals : goals} income={income} />;
  }

  return (
    <>
      {content}
      {showGoalForm && (
        <GoalForm
          onClose={() => {
            setShowGoalForm(false);
            setEditGoal(null);
          }}
          onAddGoal={handleSaveGoal}
          editGoal={editGoal}
        />
      )}
    </>
  );
};

const App = () => (
  <Layout>
    <AppContent />
  </Layout>
);

export default App;
